-- ============================================================
-- Prodigia — Proceso 1, notación (docs/PLAN_REVISION_CONTENIDO.md):
-- pasa a la convención $...$ (KaTeX, ver MathText.tsx) el contenido de
-- Calculia y Circuitia que seguía en texto plano con notación unicode
-- (x⁴, 1/x, ∫, R_eq, 10Ω...) y por eso se veía como "x^4" y "1/x" en la
-- pantalla, aunque los generadores de práctica ya emiten LaTeX:
--
--   - las 7 lecciones del Curso Pro de Calculia (0170): pasos y quiz;
--   - las 7 lecciones del Curso Pro de Circuitia (0171): pasos y quiz;
--   - las 5 técnicas rápidas de Circuitia (0167 pasos + 0179 quiz);
--   - el quiz de las 5 técnicas rápidas de Calculia (0178; sus pasos ya
--     se convirtieron en 0181).
--
-- El CONTENIDO matemático no cambia, solo cómo se escribe. INVARIANTE
-- del quiz: cada `respuesta` sigue siendo EXACTAMENTE uno de los strings
-- de `opciones` (mismo texto, con los mismos $...$): el servidor valida por
-- igualdad exacta en /api/aprender/completar. Verificado por script antes
-- de escribir este archivo: cada respuesta ∈ opciones y cada fórmula
-- compila en KaTeX con throwOnError.
--
-- Migración nueva sobre filas existentes (update por slug): nunca se
-- editaron 0165/0167/0170/0171/0178/0179/0181.
-- ============================================================

update public.techniques
set contenido = '{"pasos":["La derivada de $f(x)$ en un punto es la pendiente de la recta tangente ahí — qué tan rápido cambia $f(x)$ cuando x cambia un poquito. No es un truco algebraico suelto: es una medida de razón de cambio.","Regla de la potencia: si $f(x) = c\\cdot x^{n}$, entonces $f''(x) = c\\cdot n\\cdot x^{n-1}$. Se baja el exponente como factor multiplicando al coeficiente, y se le resta 1 al exponente.","Ejemplo resuelto: deriva $f(x) = 5x^{4}$. Coeficiente $c=5$, exponente $n=4$. Aplicando la regla: $f''(x) = 5\\cdot 4\\cdot x^{4-1} = 20x^{3}$.","Verificación rápida: el exponente de la derivada SIEMPRE es uno menos que el original (4 $\\to 3$), y el coeficiente nuevo es el coeficiente viejo multiplicado por el exponente viejo $(5\\cdot 4=20)$ — si tu resultado no cumple las dos cosas, revisá el paso.","Caso especial: la derivada de una constante sola (como $f(x)=7$, que es $7\\cdot x^{0}$) es siempre 0 — no hay pendiente porque la función no cambia nunca.","Error común a evitar: olvidarse de restar 1 al exponente (dejar $x^{4}$ en vez de $x^{3}$) o no multiplicar por el exponente original — son los dos errores más frecuentes de esta regla."],"quiz":[{"pregunta":"Deriva $f(x) = 6x^{3}$ respecto de x.","opciones":["$18x^{2}$","$6x^{2}$","$18x^{3}$","$3x^{2}$"],"respuesta":"$18x^{2}$","explicacion":"Bajás el exponente (3) como factor: $6\\cdot 3=18$, y le restás 1 al exponente: $x^{3} \\to x^{2}$. Da $18x^{2}$."},{"pregunta":"¿Cuál es la derivada de una función constante, como $f(x) = 9$?","opciones":["0","9","1","$9x$"],"respuesta":"0","explicacion":"Una constante no cambia nunca — su pendiente (razón de cambio) es siempre 0, sin importar el valor de la constante."},{"pregunta":"Deriva $f(x) = 2x^{5}$ respecto de x.","opciones":["$10x^{4}$","$2x^{4}$","$10x^{5}$","$5x^{4}$"],"respuesta":"$10x^{4}$","explicacion":"Coeficiente 2 por exponente $5 = 10$, y el exponente baja de 5 a 4: $10x^{4}$."}]}'::jsonb
where slug = 'calculia-pro-derivadas-fundamentos';

update public.techniques
set contenido = '{"pasos":["Regla del producto: si $f(x) = u(x)\\cdot v(x)$, entonces $f''(x) = u''(x)\\cdot v(x) + u(x)\\cdot v''(x)$ — la derivada del primero por el segundo SIN derivar, más el primero SIN derivar por la derivada del segundo. Nunca derives u y v por separado y los multipliques entre sí, eso da un resultado distinto.","Ejemplo resuelto (producto): deriva $f(x) = (2x)(3x^{2})$. $u=2x$, $u''=2$; $v=3x^{2}$, $v''=6x$. $f''(x) = 2\\cdot 3x^{2} + 2x\\cdot 6x = 6x^{2} + 12x^{2} = 18x^{2}$.","Regla del cociente: si $f(x) = \\frac{u(x)}{v(x)}$, entonces $f''(x) = \\frac{u''v - uv''}{v^{2}}$ — el orden de la resta en el numerador importa (derivada de arriba por abajo, MENOS arriba por derivada de abajo).","Regla de la cadena: si $f(x) = (\\text{algo con } x)^{n}$ donde ese \"algo\" no es simplemente x, hay una función adentro de otra. Se deriva la función de afuera dejando lo de adentro igual, y se multiplica por la derivada de adentro.","Ejemplo resuelto (cadena): deriva $f(x) = (3x+2)^{4}$. La de afuera es $(\\text{adentro})^{4} \\to 4(\\text{adentro})^{3}$; la derivada de adentro $(3x+2)$ es $3$. Entonces $f''(x) = 4(3x+2)^{3}\\cdot 3 = 12(3x+2)^{3}$.","Cómo elegir la regla correcta de un vistazo: ¿es una multiplicación de dos expresiones? Producto. ¿Es una división? Cociente. ¿Hay un paréntesis elevado a una potencia con algo más que x adentro? Cadena — y nunca te olvides del factor de adentro."],"quiz":[{"pregunta":"Deriva $f(x) = (2x+1)^{3}$ usando la regla de la cadena.","opciones":["$6(2x+1)^{2}$","$3(2x+1)^{2}$","$6(2x+1)^{3}$","$2(2x+1)^{2}$"],"respuesta":"$6(2x+1)^{2}$","explicacion":"La de afuera da $3(2x+1)^{2}$, y hay que multiplicar por la derivada de adentro $(2x+1)'' = 2$: $3\\cdot 2=6$, queda $6(2x+1)^{2}$."},{"pregunta":"¿Qué regla usás para derivar $f(x) = \\frac{x^{2}+1}{x+3}$?","opciones":["Regla del cociente","Regla del producto","Regla de la cadena","Regla de la potencia sola"],"respuesta":"Regla del cociente","explicacion":"Es una DIVISIÓN de dos expresiones — eso siempre pide la regla del cociente, con el orden $\\text{alto}''\\cdot\\text{bajo}$ menos $\\text{alto}\\cdot\\text{bajo}''$ en el numerador."},{"pregunta":"Al aplicar la regla del producto a $f(x) = u(x)v(x)$, ¿cuál es la fórmula correcta?","opciones":["$u''v + uv''$","$u''v''$","$u''v - uv''$","uv"],"respuesta":"$u''v + uv''$","explicacion":"Es una SUMA de dos términos — derivada del primero por el segundo sin derivar, más el primero sin derivar por la derivada del segundo. Multiplicar $u''\\cdot v''$ directamente es el error más común."}]}'::jsonb
where slug = 'calculia-pro-derivadas-producto-cociente-cadena';

update public.techniques
set contenido = '{"pasos":["Integrar es el proceso INVERSO de derivar: $\\int f(x)\\,dx$ busca una función F(x) cuya derivada sea $f(x)$. Por eso siempre se agrega \"+ C\" — cualquier constante desaparece al derivar, así que hay infinitas respuestas válidas que difieren solo en una constante.","Regla de la potencia (integrales): $\\int x^{n}\\,dx = \\frac{x^{n+1}}{n+1} + C$, siempre que $n \\neq -1$. Subís el exponente en 1, y dividís por ese exponente NUEVO (nunca por el viejo).","Ejemplo resuelto: calcula $\\int 6x^{2}\\,dx$. Exponente $n=2$, sube a 3; coeficiente 6 dividido por 3 (el exponente nuevo) da 2. Entonces $\\int 6x^{2}\\,dx = 2x^{3} + C$.","Verificación (siempre se puede chequear derivando la respuesta): la derivada de $2x^{3}$ es $2\\cdot 3\\cdot x^{2} = 6x^{2}$, que es exactamente el integrando original — confirma que la antiderivada está bien.","Caso especial $n=-1$: $\\int (\\frac{1}{x})\\,dx = \\ln|x| + C$ — es el único caso donde la fórmula de arriba no funciona, porque dividir por $(n+1)=0$ sería indefinido.","Error común: copiar el integrando tal cual como si ya fuera la respuesta (sin integrar de verdad), o subir el exponente pero olvidarse de dividir por el exponente nuevo."],"quiz":[{"pregunta":"Calcula $\\int 12x^{3}\\,dx$.","opciones":["$3x^{4} + C$","$12x^{4} + C$","$3x^{3} + C$","$4x^{4} + C$"],"respuesta":"$3x^{4} + C$","explicacion":"El exponente sube de 3 a 4, y el coeficiente 12 se divide por ese exponente nuevo (4): $\\frac{12}{4}=3$. Queda $3x^{4} + C$."},{"pregunta":"¿Por qué toda integral indefinida lleva \"+ C\"?","opciones":["Porque cualquier constante desaparece al derivar, así que hay infinitas antiderivadas posibles","Es una convención sin motivo matemático","Porque C siempre vale 0","Solo se agrega en integrales de potencias"],"respuesta":"Porque cualquier constante desaparece al derivar, así que hay infinitas antiderivadas posibles","explicacion":"Si F(x) es una antiderivada de $f(x)$, F(x)+C también lo es para cualquier constante C, porque la derivada de una constante es 0."},{"pregunta":"Calcula $\\int (\\frac{1}{x})\\,dx$.","opciones":["$\\ln|x| + C$","$\\frac{1}{x^{2}} + C$","$x^{0} + C$","$-\\frac{1}{x^{2}} + C$"],"respuesta":"$\\ln|x| + C$","explicacion":"Es el único caso donde la regla de la potencia no funciona ($n=-1$ haría dividir por cero) — la antiderivada de $\\frac{1}{x}$ es siempre el logaritmo natural."}]}'::jsonb
where slug = 'calculia-pro-integrales-fundamentos';

update public.techniques
set contenido = '{"pasos":["$\\int e^{ax}\\,dx = \\frac{1}{a}e^{ax} + C$ — la exponencial es la única función que reaparece intacta al derivar, pero con coeficiente a adentro hay que dividir por a al integrar (se puede verificar derivando: la derivada de $\\frac{1}{a}e^{ax}$ es $(\\frac{1}{a})\\cdot a\\cdot e^{ax} = e^{ax}$, correcto).","$\\int \\cos(x)\\,dx = \\operatorname{sen}(x) + C$, y $\\int \\operatorname{sen}(x)\\,dx = -\\cos(x) + C$ — el signo negativo va SOLO en la integral del seno, nunca en la del coseno. Si dudás, derivá la respuesta: la derivada de $\\operatorname{sen}(x)$ es $\\cos(x)$ (correcto), la derivada de $-\\cos(x)$ es $\\operatorname{sen}(x)$ (correcto).","Sustitución simple (u $= ax+b$): sirve cuando el integrando es una potencia de una expresión LINEAL, como $(ax+b)^{n}$. La fórmula es $\\int (ax+b)^{n}\\,dx = (\\frac{1}{a(n+1)})(ax+b)^{n+1} + C$.","Ejemplo resuelto: calcula $\\int 8(2x+1)^{3}\\,dx$. Acá $a=2$, $n=3$, y el coeficiente 8 ya incluye el factor $a(n+1)=2\\cdot 4=8$ — así que el coeficiente que queda en la respuesta es $\\frac{8}{8}=1$. Resultado: $(2x+1)^{4} + C$.","Verificación: la derivada de $(2x+1)^{4}$ es $4(2x+1)^{3}\\cdot 2$ (regla de la cadena) $= 8(2x+1)^{3}$, que es exactamente el integrando original.","Cómo no perderse: identificá primero si hay una potencia externa con un binomio linear adentro (pide sustitución), si es $e^{ax}$ (pide dividir por a), o si es seno/coseno (cuidado con el signo) — nunca se mezclan las tres reglas en el mismo paso."],"quiz":[{"pregunta":"Calcula $\\int e^{3x}\\,dx$.","opciones":["$\\frac{1}{3}e^{3x} + C$","$e^{3x} + C$","$3e^3x + C$","$\\frac{1}{3}e^{x} + C$"],"respuesta":"$\\frac{1}{3}e^{3x} + C$","explicacion":"La exponencial se mantiene igual, pero hay que dividir por el coeficiente del exponente (3) para que la derivada de la respuesta vuelva a dar $e^{3x}\\cdot 3$."},{"pregunta":"Calcula $\\int \\operatorname{sen}(x)\\,dx$.","opciones":["$-\\cos(x) + C$","$\\cos(x) + C$","$-\\operatorname{sen}(x) + C$","$\\operatorname{sen}(x) + C$"],"respuesta":"$-\\cos(x) + C$","explicacion":"La derivada de $-\\cos(x)$ es $\\operatorname{sen}(x)$ (porque la derivada de $\\cos(x)$ es $-\\operatorname{sen}(x)$, y el signo se cancela) — coincide con el integrando original."},{"pregunta":"Calcula $\\int 10(2x+3)^{4}\\,dx$ usando sustitución $u=2x+3$.","opciones":["$(2x+3)^{5} + C$","$5(2x+3)^{5} + C$","$10(2x+3)^{5} + C$","$(2x+3)^{4} + C$"],"respuesta":"$(2x+3)^{5} + C$","explicacion":"$a(n+1)=2\\cdot 5=10$, y el integrando ya trae ese coeficiente (10), así que en la respuesta queda $\\frac{10}{10}=1$: $(2x+3)^{5} + C$."}]}'::jsonb
where slug = 'calculia-pro-integrales-avanzadas';

update public.techniques
set contenido = '{"pasos":["Una serie geométrica tiene la forma $a + ar + ar^{2} + ar^{3} + \\cdots$ — cada término se multiplica por la misma razón r para llegar al siguiente. Converge (tiene una suma finita) si y solo si $|r| < 1$.","Fórmula de la suma infinita (solo válida si $|r|<1$): $S = \\frac{a}{1-r}$, donde a es el primer término.","Ejemplo resuelto: calcula la suma de la serie geométrica con primer término $a=4$ y razón $r=\\frac{1}{2}$. Primero se confirma que converge: $\\left|\\frac{1}{2}\\right|<1$, sí converge. Luego: $S = \\frac{4}{1-\\frac{1}{2}} = \\frac{4}{\\frac{1}{2}} = 8$.","Si $|r| \\geq 1$ la serie geométrica DIVERGE (no tiene suma finita) — no tiene sentido aplicar la fórmula $\\frac{a}{1-r}$ en ese caso, daría un número sin significado real.","Una serie p, $\\sum \\frac{1}{n^{p}}$, es un tipo distinto de serie (no geométrica) — converge si y solo si $p>1$. No confundir el criterio: para geométricas es $|r|<1$, para series p es $p>1$.","Ejemplo de clasificación: la serie p con $p=3$ ($\\sum \\frac{1}{n^{3}}$) converge porque 3>1. La serie geométrica con $r=2$ diverge porque $|2|\\geq 1$ (cada término es más grande que el anterior, nunca se estabiliza)."],"quiz":[{"pregunta":"Calcula la suma de la serie geométrica infinita con primer término $a=6$ y razón $r=\\frac{1}{3}$.","opciones":["9","18","6","2"],"respuesta":"9","explicacion":"$S = \\frac{a}{1-r} = \\frac{6}{1-\\frac{1}{3}} = \\frac{6}{\\frac{2}{3}} = 6\\cdot\\frac{3}{2} = 9$. Primero se confirma que $\\left|\\frac{1}{3}\\right|<1$, así que converge."},{"pregunta":"¿La serie geométrica con razón $r = \\frac{3}{2}$ converge o diverge?","opciones":["Diverge","Converge","Converge solo si $a>0$","No se puede saber sin el primer término"],"respuesta":"Diverge","explicacion":"$\\left|\\frac{3}{2}\\right| = 1.5$, que es mayor o igual a 1 — la condición de convergencia $|r|<1$ no se cumple, así que diverge."},{"pregunta":"¿Para qué valores de p converge la serie p, $\\sum \\frac{1}{n^{p}}$?","opciones":["$p > 1$","$p < 1$","Cualquier p","$p = 1$"],"respuesta":"$p > 1$","explicacion":"El criterio de convergencia de una serie p es $p>1$ — un criterio totalmente distinto al de la razón $|r|<1$ de las series geométricas, no hay que mezclarlos."}]}'::jsonb
where slug = 'calculia-pro-series-geometricas';

update public.techniques
set contenido = '{"pasos":["Una derivada parcial mide cómo cambia $f(x,y)$ cuando UNA sola variable se mueve y la otra se mantiene fija. Se escribe $\\frac{\\partial f}{\\partial x}$ (respecto de x) o $\\frac{\\partial f}{\\partial y}$ (respecto de y).","La técnica es exactamente la regla de la potencia de siempre — el único cambio de hábito es tratar la otra letra como si fuera un número fijo (un coeficiente constante), nunca derivarla ni hacerla desaparecer.","Ejemplo resuelto: calcula $\\frac{\\partial f}{\\partial x}$ para $f(x,y) = 3x^{2}y^{3}$. Tratando $y^{3}$ como constante: es como derivar $3(y^{3})\\cdot x^{2}$ respecto de $x \\to 3(y^{3})\\cdot 2\\cdot x = 6xy^{3}$. Entonces $\\frac{\\partial f}{\\partial x} = 6xy^{3}$.","Ahora $\\frac{\\partial f}{\\partial y}$ de la MISMA función $f(x,y) = 3x^{2}y^{3}$: tratando $x^{2}$ como constante, derivás $3(x^{2})\\cdot y^{3}$ respecto de y $\\to 3(x^{2})\\cdot 3\\cdot y^{2} = 9x^{2}y^{2}$. Entonces $\\frac{\\partial f}{\\partial y} = 9x^{2}y^{2}$.","Verificación de que no te comiste la otra variable: en $\\frac{\\partial f}{\\partial x}$, la potencia de y $(y^{3})$ debe quedar EXACTAMENTE igual que en la función original — si desapareció, es el error más común de esta técnica.","Truco rápido: tapá con un dedo la letra que no te pidieron, derivá lo que queda visible como si fuera una función de una sola variable, después destapá y multiplicá."],"quiz":[{"pregunta":"Para $f(x,y) = 5x^{3}y^{2}$, calcula $\\frac{\\partial f}{\\partial x}$.","opciones":["$15x^{2}y^{2}$","$5x^{2}y^{2}$","$15x^{3}y$","$10x^{3}y$"],"respuesta":"$15x^{2}y^{2}$","explicacion":"Tratando $y^{2}$ como constante: $5\\cdot 3=15$, el exponente de x baja de 3 a 2, y la potencia de y $(y^{2})$ queda igual: $15x^{2}y^{2}$."},{"pregunta":"Para la misma $f(x,y) = 5x^{3}y^{2}$, calcula $\\frac{\\partial f}{\\partial y}$.","opciones":["$10x^{3}y$","$5x^{3}y$","$15x^{2}y^{2}$","$10x^{2}y$"],"respuesta":"$10x^{3}y$","explicacion":"Tratando $x^{3}$ como constante: $5\\cdot 2=10$, el exponente de y baja de 2 a 1, y la potencia de x $(x^{3})$ queda igual: $10x^{3}y$."},{"pregunta":"Al calcular $\\frac{\\partial f}{\\partial x}$ de $f(x,y)=x^{2}y^{4}$, ¿qué error es más común?","opciones":["Derivar también la y, en vez de tratarla como constante fija","Olvidarse del signo negativo","Multiplicar por y en vez de x","Usar la regla del producto"],"respuesta":"Derivar también la y, en vez de tratarla como constante fija","explicacion":"El error típico es derivar las DOS variables a la vez — cuando piden $\\frac{\\partial}{\\partial x}$, la potencia de $y$ del resultado tiene que quedar IGUAL que en el original, sin tocarla."}]}'::jsonb
where slug = 'calculia-pro-multivariable-parciales';

update public.techniques
set contenido = '{"pasos":["Una EDO (ecuación diferencial ordinaria) separable es aquella donde $\\frac{dy}{dx}$ se puede reescribir como $f(x)\\cdot g(y)$ — un factor que solo tiene x, multiplicado por otro que solo tiene y. Si podés hacer eso, siempre se puede resolver por separación de variables.","Paso 1: reordenar para dejar todo lo de $y$ (incluido $dy$) de un lado, y todo lo de $x$ (incluido $dx$) del otro: $\\frac{dy}{g(y)} = f(x)\\,dx$.","Paso 2: integrar cada lado por separado, cada uno con su propia constante — las dos constantes se combinan en una sola al final.","Ejemplo resuelto: resuelve $\\frac{dy}{dx} = 2xy$. Separando: $\\frac{dy}{y} = 2x\\,dx$. Integrando ambos lados: $\\ln|y| = x^{2} + C_{1}$ (usando la regla de la potencia de integrales del lado derecho, y $\\int \\frac{dy}{y} = \\ln|y|$ del lado izquierdo).","Paso 3 (despejar $y$): aplicar exponencial en ambos lados de $\\ln|y| = x^{2} + C_{1}$ da $|y| = e^{x^{2}+C_{1}} = e^{C_{1}}\\cdot e^{x^{2}}$. Como $e^{C_{1}}$ es solo otra constante positiva, se renombra como $A$: $y = A\\cdot e^{x^{2}}$.","Verificación: si $y = A\\cdot e^{x^{2}}$, entonces $\\frac{dy}{dx} = A\\cdot e^{x^{2}}\\cdot 2x = 2x\\cdot y$ (usando que $A\\cdot e^{x^{2}}=y$) — coincide exactamente con la ecuación original $\\frac{dy}{dx} = 2xy$, confirma que la solución está bien."],"quiz":[{"pregunta":"¿Cuál es el primer paso para resolver una EDO separable $\\frac{dy}{dx} = f(x)\\cdot g(y)$?","opciones":["Separar: $\\frac{dy}{g(y)} = f(x)\\,dx$","Integrar directamente sin reordenar","Derivar ambos lados","Reemplazar y por una constante"],"respuesta":"Separar: $\\frac{dy}{g(y)} = f(x)\\,dx$","explicacion":"El nombre \"separable\" viene de este paso — hay que dejar toda la y (con $dy$) de un lado y toda la x (con $dx$) del otro ANTES de integrar."},{"pregunta":"Resuelve la EDO separable $\\frac{dy}{dx} = 3x^{2}y$ (deja la respuesta en términos de la constante A).","opciones":["$y = A\\cdot e^{x^{3}}$","$y = A\\cdot e^{3x^{2}}$","$y = A\\cdot x^{3}$","$y = A\\cdot e^{x^{2}}$"],"respuesta":"$y = A\\cdot e^{x^{3}}$","explicacion":"Separando: $\\frac{dy}{y}=3x^{2}\\,dx$. Integrando: $\\ln|y|=x^{3}+C_{1}$ (la antiderivada de $3x^{2}$ es $x^{3}$). Despejando $y$ con exponencial: $y=A\\cdot e^{x^{3}}$."},{"pregunta":"Al despejar y de $\\ln|y| = x^{2} + C_{1}$, ¿qué operación hay que aplicar en ambos lados?","opciones":["La función exponencial (elevar e a cada lado)","El logaritmo otra vez","Elevar al cuadrado","Dividir por $x^{2}$"],"respuesta":"La función exponencial (elevar e a cada lado)","explicacion":"Exponencial y logaritmo natural son operaciones inversas — aplicar $e^{(\\cdots)}$ a ambos lados de $\\ln|y| = \\cdots$ deshace el logaritmo y despeja $y$."}]}'::jsonb
where slug = 'calculia-pro-edos-separables';

update public.techniques
set contenido = '{"pasos":["Ley de Ohm: $V = I\\cdot R$. El voltaje sobre un resistor es directamente proporcional a la corriente que lo atraviesa, con la resistencia como factor de proporcionalidad — cuanto más grande R, más voltaje hace falta para la misma corriente.","En un circuito en SERIE, los resistores están uno detrás de otro formando un único camino, sin bifurcaciones — la carga no tiene otro lugar por dónde irse, así que la MISMA corriente atraviesa a todos los resistores de la cadena.","Ejemplo resuelto: un circuito en serie con $R_{1}=10\\,\\Omega$ y $R_{2}=20\\,\\Omega$, alimentado por una fuente de $12\\,\\text{V}$. Primero la resistencia equivalente: $R_{\\text{eq}} = R_{1} + R_{2} = 10 + 20 = 30\\,\\Omega$. Luego la corriente total con la Ley de Ohm: $I = \\frac{V}{R_{\\text{eq}}} = \\frac{12}{30} = 0.4\\,\\text{A}$ — esa es la corriente en TODO el circuito, en $R_{1}$ y en $R_{2}$ por igual.","Con esa corriente, el voltaje de cada resistor sale de aplicar $V=IR$ a cada uno por separado: $V_{R_{1}} = 0.4\\cdot 10 = 4\\,\\text{V}$, $V_{R_{2}} = 0.4\\cdot 20 = 8\\,\\text{V}$.","Verificación (siempre se puede chequear): la suma de los voltajes de cada resistor tiene que dar exactamente el voltaje de la fuente. $4\\,\\text{V} + 8\\,\\text{V} = 12\\,\\text{V}$ ✓ — coincide con la fuente, confirma que el reparto está bien.","Error común a evitar: pensar que la corriente también se \"reparte\" entre los resistores como el voltaje — en serie es al revés: la corriente es la misma en todos, y es el VOLTAJE el que se reparte según el tamaño de cada resistor."],"quiz":[{"pregunta":"Un circuito en serie tiene $R_{1}=5\\,\\Omega$ y $R_{2}=15\\,\\Omega$, con una fuente de $20\\,\\text{V}$. ¿Cuál es la corriente total?","opciones":["$1\\,\\text{A}$","$4\\,\\text{A}$","$0.75\\,\\text{A}$","$20\\,\\text{A}$"],"respuesta":"$1\\,\\text{A}$","explicacion":"$R_{\\text{eq}} = 5+15 = 20\\,\\Omega$. Con la Ley de Ohm: $I = \\frac{V}{R_{\\text{eq}}} = \\frac{20}{20} = 1\\,\\text{A}$."},{"pregunta":"¿Qué es cierto sobre la corriente en un circuito en serie simple (un solo camino, sin bifurcaciones)?","opciones":["Es la misma en todos los resistores","Se reparte distinto en cada resistor","Es cero en el segundo resistor","Depende de qué resistor mires primero"],"respuesta":"Es la misma en todos los resistores","explicacion":"En serie no hay otro camino para la carga — la misma corriente atraviesa cada resistor, uno tras otro."},{"pregunta":"En el circuito del ejemplo ($R_{1}=10\\,\\Omega$, $R_{2}=20\\,\\Omega$, fuente de $12\\,\\text{V}$, corriente $0.4\\,\\text{A}$), ¿cuánto vale el voltaje sobre $R_{2}$?","opciones":["$8\\,\\text{V}$","$4\\,\\text{V}$","$12\\,\\text{V}$","$0.4\\,\\text{V}$"],"respuesta":"$8\\,\\text{V}$","explicacion":"$V=IR$: $0.4\\,\\text{A}\\times 20\\,\\Omega=8\\,\\text{V}$. Y se puede comprobar: $4\\,\\text{V}$ (en $R_{1}$) + $8\\,\\text{V}$ (en $R_{2}$) $= 12\\,\\text{V}$, el total de la fuente."}]}'::jsonb
where slug = 'circuitia-pro-fundamentos-ohm-serie';

update public.techniques
set contenido = '{"pasos":["En un circuito en PARALELO, dos o más resistores están conectados a los mismos dos puntos (nodos) — por eso el voltaje sobre cada uno de ellos es EXACTAMENTE el mismo, sin importar cuánta resistencia tenga cada rama.","Es lo contrario de lo que pasa en serie: ahí la corriente era compartida y el voltaje se repartía; en paralelo es el VOLTAJE el que es compartido y la CORRIENTE la que se reparte entre las ramas.","Ejemplo resuelto: $R_{1}=10\\,\\Omega$ y $R_{2}=20\\,\\Omega$ en paralelo, con una fuente de $12\\,\\text{V}$. Cada resistor ve el voltaje completo de la fuente: $12\\,\\text{V}$ sobre $R_{1}$ y $12\\,\\text{V}$ sobre $R_{2}$ también.","Reparto de corriente (divisor de corriente): cada rama saca su propia corriente con Ley de Ohm usando SU resistencia: $I_{R_{1}} = \\frac{V}{R_{1}} = \\frac{12}{10} = 1.2\\,\\text{A}$. $I_{R_{2}} = \\frac{V}{R_{2}} = \\frac{12}{20} = 0.6\\,\\text{A}$.","Verificación con la resistencia equivalente: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{10} + \\frac{1}{20} = 0.15$, entonces $R_{\\text{eq}} = 6.6667\\,\\Omega$, y la corriente total que entrega la fuente es $I_{\\text{total}} = \\frac{V}{R_{\\text{eq}}} = \\frac{12}{6.6667} = 1.8\\,\\text{A}$ — que coincide con $I_{R_{1}} + I_{R_{2}} = 1.2 + 0.6 = 1.8\\,\\text{A}$ ✓.","Insight clave: el resistor con MENOS resistencia se lleva MÁS corriente (es el camino \"más fácil\") — es la relación inversa. Error común: pensar que más resistencia atrae más corriente, es exactamente al revés."],"quiz":[{"pregunta":"$R_{1}=10\\,\\Omega$ y $R_{2}=20\\,\\Omega$ están en paralelo con una fuente de $12\\,\\text{V}$. ¿Cuál es la corriente que pasa por $R_{1}$?","opciones":["$1.2\\,\\text{A}$","$0.6\\,\\text{A}$","$1.8\\,\\text{A}$","$2\\,\\text{A}$"],"respuesta":"$1.2\\,\\text{A}$","explicacion":"En paralelo cada resistor ve el voltaje completo de la fuente: $I = \\frac{V}{R} = \\frac{12}{10} = 1.2\\,\\text{A}$."},{"pregunta":"¿Qué es cierto sobre el voltaje en una conexión en paralelo?","opciones":["Es el mismo en todas las ramas","Se reparte entre las ramas","Es cero en la segunda rama","Depende de la corriente que traiga cada rama"],"respuesta":"Es el mismo en todas las ramas","explicacion":"Todas las ramas en paralelo están conectadas a los mismos dos nodos, así que ven exactamente el mismo voltaje."},{"pregunta":"Si dos resistores IGUALES están en paralelo, ¿cómo se reparte la corriente total entre ellos?","opciones":["Se reparte por igual entre los dos","Toda va al primero","Toda va al segundo","Depende de cuál esté dibujado arriba"],"respuesta":"Se reparte por igual entre los dos","explicacion":"Con la misma resistencia y el mismo voltaje compartido, $I=\\frac{V}{R}$ da exactamente el mismo valor para ambas ramas."}]}'::jsonb
where slug = 'circuitia-pro-paralelo-voltaje-corriente';

update public.techniques
set contenido = '{"pasos":["En SERIE, la resistencia equivalente es la suma directa: $R_{\\text{eq}} = R_{1} + R_{2} + \\cdots$ — agregar resistores en serie SIEMPRE aumenta (o deja igual) la resistencia total.","En PARALELO, se suman los recíprocos y se invierte al final: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$ — agregar resistores en paralelo SIEMPRE reduce (o deja igual) la resistencia total, porque se abren más caminos para la corriente.","Ejemplo comparado: dos resistores de $8\\,\\Omega$ cada uno. En serie: $R_{\\text{eq}} = 8 + 8 = 16\\,\\Omega$.","Esos mismos dos resistores de $8\\,\\Omega$, ahora en paralelo: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{8} + \\frac{1}{8} = \\frac{2}{8} = \\frac{1}{4}$, entonces $R_{\\text{eq}} = 4\\,\\Omega$ — el caso especial de dos resistores iguales en paralelo: la mitad de uno solo, nunca el doble.","Con una fuente de $8\\,\\text{V}$ sobre cada configuración: en serie, $I = \\frac{8}{16} = 0.5\\,\\text{A}$ (la misma en ambos, y cada uno se queda con $4\\,\\text{V}$ ya que son iguales). En paralelo, $I_{\\text{total}} = \\frac{8}{4} = 2\\,\\text{A}$, repartida en partes iguales: $1\\,\\text{A}$ por cada resistor (porque tienen la misma resistencia y ven el mismo voltaje).","Chequeo de sensatez rápido: el resultado en paralelo $(4\\,\\Omega)$ SIEMPRE tiene que ser menor o igual que el resistor más chico de la rama $(8\\,\\Omega)$ — si te da mayor, invertiste algo de más o de menos en la fórmula de recíprocos."],"quiz":[{"pregunta":"Dos resistores de $8\\,\\Omega$ cada uno están en serie. ¿Cuál es la resistencia equivalente?","opciones":["$16\\,\\Omega$","$4\\,\\Omega$","$8\\,\\Omega$","$64\\,\\Omega$"],"respuesta":"$16\\,\\Omega$","explicacion":"En serie se suman directo: $8+8=16\\,\\Omega$."},{"pregunta":"Esos mismos dos resistores de $8\\,\\Omega$, ahora en paralelo. ¿Cuál es la resistencia equivalente?","opciones":["$4\\,\\Omega$","$16\\,\\Omega$","$8\\,\\Omega$","$2\\,\\Omega$"],"respuesta":"$4\\,\\Omega$","explicacion":"$\\frac{1}{R_{\\text{eq}}}=\\frac{1}{8}+\\frac{1}{8}=\\frac{1}{4}$, así que $R_{\\text{eq}}=4\\,\\Omega$ — la mitad de uno solo, el caso especial de dos resistores iguales en paralelo."},{"pregunta":"¿Cuál es la fórmula correcta para la resistencia equivalente de varios resistores en PARALELO?","opciones":["$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$","$R_{\\text{eq}} = R_{1} + R_{2} + \\cdots$","$R_{\\text{eq}} = (R_{1} + R_{2}) / 2$","$R_{\\text{eq}} = R_{1} + R_{2} + 10$"],"respuesta":"$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\cdots$","explicacion":"Es la suma de recíprocos, invertida al final — nunca la suma directa (esa es la fórmula de serie, no la de paralelo)."}]}'::jsonb
where slug = 'circuitia-pro-resistencia-equivalente-comparacion';

update public.techniques
set contenido = '{"pasos":["Un circuito mixto combina una rama en serie con un bloque en paralelo incrustado adentro — se resuelve de ADENTRO hacia AFUERA, nunca sumando todo de una sola vez.","Cómo encontrar el bloque en paralelo de un vistazo: buscá el grupo de resistores que comparten los mismos dos nodos — suele estar dibujado como el tramo más anidado o más chico del circuito, no en la línea principal.","Ejemplo resuelto: un circuito en serie con $R_{s1}=10\\,\\Omega$ y un bloque en paralelo formado por $R_{p1}=20\\,\\Omega$ y $R_{p2}=20\\,\\Omega$.","Paso 1 — colapsar el bloque en paralelo SOLO (en aislamiento, antes de tocar $R_{s1}$): $\\frac{1}{R_{\\text{bloque}}} = \\frac{1}{20} + \\frac{1}{20} = \\frac{1}{10}$, entonces $R_{\\text{bloque}} = 10\\,\\Omega$.","Paso 2 — con el bloque ya colapsado a un único valor, el circuito completo queda como una serie simple de dos resistores: $R_{\\text{eq total}} = R_{s1} + R_{\\text{bloque}} = 10 + 10 = 20\\,\\Omega$.","Error común a evitar: sumar $R_{s1} + R_{p1} + R_{p2}$ todos juntos como si los tres estuvieran en serie — $R_{p1}$ y $R_{p2}$ tienen que colapsarse a UN solo valor con la fórmula de recíprocos ANTES de poder sumarlos con el resto de la serie."],"quiz":[{"pregunta":"En un circuito serie con $R_{s1}=10\\,\\Omega$ y un bloque en paralelo de $R_{p1}=20\\,\\Omega$ y $R_{p2}=20\\,\\Omega$, ¿cuál es la resistencia equivalente del bloque en paralelo, antes de sumarlo al resto?","opciones":["$10\\,\\Omega$","$20\\,\\Omega$","$40\\,\\Omega$","$5\\,\\Omega$"],"respuesta":"$10\\,\\Omega$","explicacion":"$\\frac{1}{R_{\\text{bloque}}}=\\frac{1}{20}+\\frac{1}{20}=\\frac{1}{10}$, entonces $R_{\\text{bloque}}=10\\,\\Omega$ — el caso de dos resistores iguales en paralelo, la mitad de uno solo."},{"pregunta":"Con $R_{s1}=10\\,\\Omega$ y el bloque en paralelo ya colapsado a $10\\,\\Omega$, ¿cuál es la resistencia equivalente del circuito completo?","opciones":["$20\\,\\Omega$","$10\\,\\Omega$","$30\\,\\Omega$","$200\\,\\Omega$"],"respuesta":"$20\\,\\Omega$","explicacion":"Ahora es una serie simple de dos valores: $10\\,\\Omega$ ($R_{s1}$) $+ 10\\,\\Omega$ (el bloque colapsado) $= 20\\,\\Omega$."},{"pregunta":"¿Cuál es el primer paso correcto para leer un circuito mixto (serie con un bloque en paralelo adentro)?","opciones":["Identificar el bloque en paralelo y calcular su resistencia equivalente primero","Sumar directamente todas las resistencias sin mirar cómo están conectadas","Ignorar el bloque en paralelo y tratarlo como si no estuviera","Calcular la corriente antes de conocer ninguna resistencia"],"respuesta":"Identificar el bloque en paralelo y calcular su resistencia equivalente primero","explicacion":"El bloque en paralelo tiene que colapsarse a UN solo valor antes de poder sumarlo en serie con el resto — nunca se mezclan las dos fórmulas sobre los mismos resistores sueltos."}]}'::jsonb
where slug = 'circuitia-pro-mixtos-identificar-bloque';

update public.techniques
set contenido = '{"pasos":["El algoritmo completo tiene dos pasadas: 1) de ABAJO hacia ARRIBA, se calcula la resistencia equivalente total y con eso la corriente total que entrega la fuente; 2) de ARRIBA hacia ABAJO, se reparte esa corriente/voltaje desde la fuente hasta cada resistor, respetando que en serie la corriente es compartida y en paralelo el voltaje es compartido.","Ejemplo resuelto: $R_{s1}=5\\,\\Omega$ en serie con un bloque en paralelo ($R_{p1}=20\\,\\Omega$, $R_{p2}=20\\,\\Omega$) y luego $R_{s2}=5\\,\\Omega$, con una fuente de $20\\,\\text{V}$.","Pasada 1 (abajo hacia arriba): primero el bloque, $\\frac{1}{R_{\\text{bloque}}} = \\frac{1}{20} + \\frac{1}{20} = \\frac{1}{10} \\to R_{\\text{bloque}} = 10\\,\\Omega$. Después la serie completa: $R_{\\text{eq total}} = R_{s1} + R_{\\text{bloque}} + R_{s2} = 5 + 10 + 5 = 20\\,\\Omega$. Y con eso, la corriente total: $I_{\\text{total}} = \\frac{V}{R_{\\text{eq}}} = \\frac{20}{20} = 1\\,\\text{A}$ — esta corriente atraviesa $R_{s1}$, el bloque (como conjunto) y $R_{s2}$, porque los tres están en serie entre sí.","Pasada 2 (arriba hacia abajo, primer nivel): cada tramo en serie se queda con $V=I_{\\text{total}}\\times R_{\\text{tramo}}$. $V_{R_{s1}} = 1\\times 5 = 5\\,\\text{V}$. $V_{\\text{bloque}} = 1\\times 10 = 10\\,\\text{V}$. $V_{R_{s2}} = 1\\times 5 = 5\\,\\text{V}$. Verificación: $5+10+5 = 20\\,\\text{V}$, exactamente el voltaje de la fuente ✓.","Pasada 2 (un nivel más adentro, dentro del bloque): ahora $R_{p1}$ y $R_{p2}$ comparten el voltaje del bloque que ya calculaste $(10\\,\\text{V})$ — cada uno saca su propia corriente con Ley de Ohm: $I_{R_{p1}} = \\frac{10}{20} = 0.5\\,\\text{A}$, $I_{R_{p2}} = \\frac{10}{20} = 0.5\\,\\text{A}$.","Verificación final: toda la corriente que entra al bloque tiene que salir repartida entre sus ramas — $I_{R_{p1}} + I_{R_{p2}} = 0.5 + 0.5 = 1\\,\\text{A}$, que coincide exactamente con $I_{\\text{total}}$. Si esa suma no coincidiera, algo se calculó mal en algún paso anterior."],"quiz":[{"pregunta":"En el circuito $R_{s1}=5\\,\\Omega$ + bloque paralelo ($10\\,\\Omega$ equivalente) + $R_{s2}=5\\,\\Omega$, con fuente de $20\\,\\text{V}$, ¿cuál es la corriente total que entrega la fuente?","opciones":["$1\\,\\text{A}$","$2\\,\\text{A}$","$0.5\\,\\text{A}$","$4\\,\\text{A}$"],"respuesta":"$1\\,\\text{A}$","explicacion":"$R_{\\text{eq total}} = 5+10+5 = 20\\,\\Omega$. $I = \\frac{V}{R} = \\frac{20}{20} = 1\\,\\text{A}$."},{"pregunta":"Con esa corriente total de $1\\,\\text{A}$, ¿cuál es el voltaje sobre el bloque en paralelo ($10\\,\\Omega$ equivalente)?","opciones":["$10\\,\\text{V}$","$5\\,\\text{V}$","$20\\,\\text{V}$","$1\\,\\text{V}$"],"respuesta":"$10\\,\\text{V}$","explicacion":"$V=IR$: $1\\,\\text{A}\\times 10\\,\\Omega=10\\,\\text{V}$ — el bloque completo actúa como un solo resistor de $10\\,\\Omega$ dentro de la serie."},{"pregunta":"Sabiendo que el bloque en paralelo tiene $10\\,\\text{V}$ en sus terminales y $R_{p1}=R_{p2}=20\\,\\Omega$, ¿cuánta corriente pasa por $R_{p1}$?","opciones":["$0.5\\,\\text{A}$","$1\\,\\text{A}$","$0.25\\,\\text{A}$","$2\\,\\text{A}$"],"respuesta":"$0.5\\,\\text{A}$","explicacion":"Dentro del bloque, cada rama ve el voltaje compartido del bloque $(10\\,\\text{V})$: $I=\\frac{V}{R}=\\frac{10}{20}=0.5\\,\\text{A}$."}]}'::jsonb
where slug = 'circuitia-pro-mixtos-resolver-paso-a-paso';

update public.techniques
set contenido = '{"pasos":["Regla general: en un camino en serie único, aumentar la resistencia en cualquier punto SIEMPRE reduce (o deja igual) la corriente total; nunca la aumenta. Y al revés: reducir una resistencia siempre aumenta (o deja igual) la corriente.","Circuito base: serie con $R_{1}=10\\,\\Omega$ y $R_{2}=10\\,\\Omega$, fuente de $20\\,\\text{V}$. $R_{\\text{eq}} = 20\\,\\Omega$, corriente base $I = \\frac{20}{20} = 1\\,\\text{A}$ — la misma en $R_{1}$ y en $R_{2}$, por estar en serie.","Perturbación A — $R_{1}$ se duplica a $20\\,\\Omega$: nuevo $R_{\\text{eq}} = 20+10 = 30\\,\\Omega$, nueva corriente $I = \\frac{20}{30} \\approx 0.667\\,\\text{A}$. Resultado: DISMINUYE respecto de la base (de $1\\,\\text{A}$ a $\\approx 0.667\\,\\text{A}$), porque el camino ahora tiene más resistencia total.","Perturbación B — en cambio, $R_{1}$ se reduce a la mitad, a $5\\,\\Omega$: nuevo $R_{\\text{eq}} = 5+10 = 15\\,\\Omega$, nueva corriente $I = \\frac{20}{15} \\approx 1.333\\,\\text{A}$. Resultado: AUMENTA respecto de la base (de $1\\,\\text{A}$ a $\\approx 1.333\\,\\text{A}$), porque el camino ahora tiene menos resistencia total.","Por qué funciona sin resolver todo: en un camino en serie único, la corriente depende únicamente de la resistencia TOTAL de ese camino $(I=\\frac{V}{R_{\\text{eq}}})$ — si esa suma sube, la corriente baja (o queda igual); si esa suma baja, la corriente sube (o queda igual). Nunca al revés.","Aplicación rápida: para estimar la DIRECCIÓN del cambio alcanza con preguntarse \"¿la resistencia total del camino subió o bajó?\" — no hace falta recalcular el circuito completo para eso, aunque para el VALOR exacto sí hay que resolverlo paso a paso."],"quiz":[{"pregunta":"En un circuito en serie $R_{1}=10\\,\\Omega$ y $R_{2}=10\\,\\Omega$ con fuente de $20\\,\\text{V}$ (corriente base $1\\,\\text{A}$), si $R_{1}$ se duplica a $20\\,\\Omega$, ¿qué le pasa a la corriente total?","opciones":["Disminuye","Aumenta","No cambia","Se vuelve cero"],"respuesta":"Disminuye","explicacion":"La resistencia total sube de $20\\,\\Omega$ a $30\\,\\Omega$, así que la corriente baja: de $1\\,\\text{A}$ a $\\frac{20}{30}\\approx 0.67\\,\\text{A}$."},{"pregunta":"En el mismo circuito, si en cambio $R_{1}$ se reduce a la mitad (a $5\\,\\Omega$), ¿qué le pasa a la corriente total?","opciones":["Aumenta","Disminuye","No cambia","Se vuelve infinita"],"respuesta":"Aumenta","explicacion":"La resistencia total baja de $20\\,\\Omega$ a $15\\,\\Omega$, así que la corriente sube: de $1\\,\\text{A}$ a $\\frac{20}{15}\\approx 1.33\\,\\text{A}$."},{"pregunta":"¿Por qué aumentar la resistencia de cualquier resistor en un circuito en serie simple SIEMPRE hace que la corriente baje o se mantenga, nunca que suba?","opciones":["Porque la resistencia total del circuito (la suma de todas) solo puede aumentar o quedar igual, nunca bajar","Porque la fuente reduce su voltaje automáticamente al detectar el cambio","Porque la corriente elige el camino más corto disponible","Porque los resistores en serie se anulan entre sí"],"respuesta":"Porque la resistencia total del circuito (la suma de todas) solo puede aumentar o quedar igual, nunca bajar","explicacion":"En serie, $R_{\\text{eq}}$ es una SUMA de resistencias positivas — agregar más nunca puede achicar esa suma, y una corriente mayor $(I=\\frac{V}{R_{\\text{eq}}})$ necesitaría un $R_{\\text{eq}}$ menor, no mayor."}]}'::jsonb
where slug = 'circuitia-pro-cualitativo-sube-o-baja';

update public.techniques
set contenido = '{"pasos":["En un bloque en paralelo conectado DIRECTO a la fuente, cada rama ve siempre el mismo voltaje (el de la fuente), sin importar qué pase en las ramas hermanas — y como la corriente de cada rama es $I=\\frac{V}{R_{\\text{propia}}}$, esa corriente TAMPOCO depende de las hermanas.","Caso concreto, ya verificado en el kernel de resolución (resolver.test.ts): circuito en paralelo con $R_{1}=4\\,\\Omega$, $R_{2}=6\\,\\Omega$ y $R_{3}=12\\,\\Omega$, fuente de $12\\,\\text{V}$. Corrientes base: $I_{R_{1}} = \\frac{12}{4} = 3\\,\\text{A}$, $I_{R_{2}} = \\frac{12}{6} = 2\\,\\text{A}$, $I_{R_{3}} = \\frac{12}{12} = 1\\,\\text{A}$.","Perturbación: $R_{2}$ se duplica a $12\\,\\Omega$. Nueva $I_{R_{2}} = \\frac{12}{12} = 1\\,\\text{A}$ — esa SÍ cambió (de $2\\,\\text{A}$ a $1\\,\\text{A}$), tiene sentido porque cambió SU PROPIA resistencia.","Pero $I_{R_{3}}$ sigue siendo $\\frac{12}{12} = 1\\,\\text{A}$, exactamente igual que antes — NO CAMBIA, aunque $R_{2}$ (su \"hermana\" en el mismo bloque) haya cambiado. Por la misma razón, $I_{R_{1}}$ tampoco cambia (sigue en $3\\,\\text{A}$).","Por qué no es un error de cálculo: el voltaje que ve $R_{3}$ es siempre el de la fuente ($12\\,\\text{V}$, fijo), porque $R_{3}$ está conectado directo a los mismos dos nodos que la fuente — la resistencia de $R_{2}$ no entra en ninguna cuenta de $I_{R_{3}}=\\frac{V}{R_{3}}$. Cambiar $R_{2}$ sí cambia cuánta corriente TOTAL entrega la fuente (de $6\\,\\text{A}$ a $5\\,\\text{A}$), pero esa diferencia la absorbe SOLO la rama que cambió, no las hermanas.","Error común a evitar: asumir que \"cambiar algo en el circuito siempre afecta a todo el circuito\". En un bloque en paralelo puro conectado directo a la fuente, un cambio en una rama queda aislado en esa rama; solo se propagaría a las hermanas si hubiera algo en serie compartido entre el bloque y la fuente (como en las lecciones de circuitos mixtos)."],"quiz":[{"pregunta":"En un circuito en paralelo con $R_{1}=4\\,\\Omega$, $R_{2}=6\\,\\Omega$ y $R_{3}=12\\,\\Omega$ conectados directo a una fuente de $12\\,\\text{V}$, si $R_{2}$ se duplica a $12\\,\\Omega$, ¿qué le pasa a la corriente en $R_{3}$?","opciones":["No cambia","Aumenta","Disminuye","Se vuelve cero"],"respuesta":"No cambia","explicacion":"$I_{R_{3}}=\\frac{V}{R_{3}}=\\frac{12}{12}=1\\,\\text{A}$ antes y después — no depende de $R_{2}$ porque $R_{3}$ sigue viendo el mismo voltaje de la fuente."},{"pregunta":"¿Por qué la corriente de $R_{3}$ no cambia en ese caso, aunque $R_{2}$ sí haya cambiado?","opciones":["Porque en un bloque en paralelo conectado directo a la fuente, cada rama ve siempre el mismo voltaje fijo, y su corriente depende solo de su propia resistencia","Porque $R_{3}$ está dibujado más lejos de la fuente que $R_{2}$","Porque la corriente total del circuito nunca cambia","Porque $R_{2}$ y $R_{3}$ se cancelan entre sí"],"respuesta":"Porque en un bloque en paralelo conectado directo a la fuente, cada rama ve siempre el mismo voltaje fijo, y su corriente depende solo de su propia resistencia","explicacion":"El voltaje de un bloque en paralelo puro conectado a la fuente es siempre el de la fuente — ninguna rama hermana puede cambiar ese valor para $R_{3}$."},{"pregunta":"¿Qué SÍ cambia en ese mismo circuito cuando $R_{2}$ se duplica?","opciones":["La corriente que pasa por $R_{2}$ mismo, y la corriente total que entrega la fuente","La corriente de $R_{1}$","El voltaje de $R_{3}$","Nada cambia en absoluto"],"respuesta":"La corriente que pasa por $R_{2}$ mismo, y la corriente total que entrega la fuente","explicacion":"$I_{R_{2}}$ baja de $2\\,\\text{A}$ a $1\\,\\text{A}$ (su propia resistencia cambió), y por lo tanto la corriente total de la fuente baja de $6\\,\\text{A}$ a $5\\,\\text{A}$ — pero eso no altera a las ramas hermanas que no cambiaron."}]}'::jsonb
where slug = 'circuitia-pro-cualitativo-cuando-no-cambia';

update public.techniques
set contenido = '{"pasos":["¿Los resistores forman un único camino, uno detrás del otro, sin bifurcaciones? Es serie — la corriente es la misma en todos.","¿Cada resistor tiene sus dos extremos conectados a los mismos dos puntos (nodos)? Es paralelo — el voltaje es el mismo en todos.","¿Hay una rama en serie que en algún tramo se abre en 2 o más caminos que después se vuelven a juntar? Es un circuito mixto — combina las dos reglas por partes.","Un resistor solo, sin compañía, técnicamente es tanto serie como paralelo consigo mismo — no hace falta ninguna fórmula especial."],"quiz":[{"pregunta":"Los resistores forman un único camino, uno detrás del otro, sin bifurcaciones. ¿Qué tipo de conexión es?","opciones":["Serie","Paralelo","Mixto","Ninguna de las anteriores"],"respuesta":"Serie","explicacion":"Es la definición de serie: un solo camino, la corriente es la misma en todos los resistores."},{"pregunta":"Cada resistor tiene sus dos extremos conectados a los mismos dos puntos (nodos). ¿Qué tipo de conexión es?","opciones":["Paralelo","Serie","Mixto","No se puede saber sin los valores de resistencia"],"respuesta":"Paralelo","explicacion":"Es la definición de paralelo: mismos dos nodos compartidos, el voltaje es el mismo en todos los resistores."},{"pregunta":"Una rama en serie que en algún tramo se abre en 2 o más caminos que después se vuelven a juntar, ¿qué tipo de circuito es?","opciones":["Mixto","Serie puro","Paralelo puro","No es un circuito válido"],"respuesta":"Mixto","explicacion":"Combina las dos reglas por partes — el bloque que se abre y se vuelve a juntar es la parte en paralelo, el resto sigue las reglas de serie."}]}'::jsonb
where slug = 'circuitia-reconocer-serie-vs-paralelo';

update public.techniques
set contenido = '{"pasos":["En serie, las resistencias se suman directo: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$ — mientras más resistores, más resistencia total.","En paralelo, se suman los RECÍPROCOS: $\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, y al final invertís el resultado — mientras más resistores, MENOS resistencia total.","Caso especial fácil de recordar: dos resistores iguales R en paralelo dan $\\frac{R}{2}$ — la mitad, no el doble.","Chequeo rápido de sensatez: si tu resultado de un cálculo en paralelo te dio MAYOR que el resistor más chico de la rama, algo salió mal — invertiste algo de más o de menos."],"quiz":[{"pregunta":"¿Cómo se calcula la resistencia equivalente de resistores en SERIE?","opciones":["Se suman directo: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$","Se suman los recíprocos y se invierte","Se promedian","Se multiplican entre sí"],"respuesta":"Se suman directo: $R_{\\text{eq}} = R_{1} + R_{2} + R_{3}$","explicacion":"En serie, mientras más resistores agregues, más resistencia total — la suma es directa, sin recíprocos."},{"pregunta":"¿Cómo se calcula la resistencia equivalente de resistores en PARALELO?","opciones":["$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, y al final se invierte el resultado","Se suman directo, igual que en serie","Se resta la más chica de la más grande","Se toma solo la resistencia más chica del grupo"],"respuesta":"$\\frac{1}{R_{\\text{eq}}} = \\frac{1}{R_{1}} + \\frac{1}{R_{2}} + \\frac{1}{R_{3}}$, y al final se invierte el resultado","explicacion":"En paralelo se suman los RECÍPROCOS — mientras más resistores agregues, MENOS resistencia total, al revés que en serie."},{"pregunta":"Dos resistores iguales de valor R, conectados en paralelo, dan una resistencia equivalente de...","opciones":["$\\frac{R}{2}$","2R","R","$R^{2}$"],"respuesta":"$\\frac{R}{2}$","explicacion":"Es el caso especial fácil de recordar: la mitad, no el doble — sirve como chequeo rápido de sensatez de cualquier cálculo en paralelo."}]}'::jsonb
where slug = 'circuitia-formula-resistencia-paralelo';

update public.techniques
set contenido = '{"pasos":["En SERIE: la corriente es la misma para todos (no tiene otro camino por donde irse) — el voltaje SE REPARTE entre los resistores según su tamaño.","En PARALELO: el voltaje es el mismo para todos (están conectados a los mismos 2 puntos) — la corriente SE REPARTE entre las ramas según su resistencia.","Un resistor con más resistencia, en serie, se queda con MÁS voltaje ($V=IR$, misma I); en paralelo, se queda con MENOS corriente ($I=\\frac{V}{R}$, mismo V) — es la relación inversa en cada caso.","Ley de Ohm $(V=IR)$ sirve siempre para UN resistor puntual — la pregunta de \"qué se comparte\" es sobre el GRUPO, no sobre un resistor solo."],"quiz":[{"pregunta":"En un grupo de resistores conectados en SERIE, ¿qué es igual en todos ellos?","opciones":["La corriente","El voltaje","La resistencia","La potencia"],"respuesta":"La corriente","explicacion":"En serie la corriente no tiene otro camino por donde irse — es la misma para todos; el voltaje se reparte según el tamaño de cada resistor."},{"pregunta":"En un grupo de resistores conectados en PARALELO, ¿qué es igual en todos ellos?","opciones":["El voltaje","La corriente","La resistencia","La potencia"],"respuesta":"El voltaje","explicacion":"En paralelo todos están conectados a los mismos 2 puntos, así que el voltaje es el mismo — la corriente se reparte según la resistencia de cada rama."},{"pregunta":"En SERIE, un resistor con más resistencia que sus vecinos (misma corriente para todos) se queda con...","opciones":["Más voltaje","Menos voltaje","La misma corriente que los demás, pero cero voltaje","Más corriente que los demás"],"respuesta":"Más voltaje","explicacion":"Por $V=IR$ con la misma I para todos, a mayor R le corresponde mayor V — es la relación inversa de lo que pasa en paralelo (ahí, a mayor R le corresponde MENOS corriente)."}]}'::jsonb
where slug = 'circuitia-voltaje-vs-corriente-compartidos';

update public.techniques
set contenido = '{"pasos":["Buscá el grupo de resistores que comparten los mismos 2 nodos (el bloque en paralelo) — suele ser el tramo más chico o más anidado del dibujo.","Calculá la resistencia equivalente de ESE bloque solo, con la fórmula de recíprocos — ahora tenés un resistor \"virtual\" único en su lugar.","Con el bloque ya colapsado a un solo valor, el circuito completo queda como una serie simple — sumá ese valor con los demás resistores en serie.","Para hallar corriente/voltaje de un resistor específico DENTRO del bloque en paralelo, primero necesitás el voltaje que le llega a todo el bloque (paso anterior), y recién ahí repartirlo."],"quiz":[{"pregunta":"Al leer un circuito mixto, ¿qué se busca y se resuelve PRIMERO?","opciones":["El bloque de resistores en paralelo (colapsarlo a un solo valor equivalente)","El resistor con el valor más grande","La fuente de voltaje","El resistor más cercano a la fuente, sin importar cómo esté conectado"],"respuesta":"El bloque de resistores en paralelo (colapsarlo a un solo valor equivalente)","explicacion":"Un circuito mixto se resuelve de adentro hacia afuera — el primer paso siempre es encontrar el grupo que comparte los mismos 2 nodos y calcular su resistencia equivalente."},{"pregunta":"Una vez que el bloque en paralelo ya está colapsado a un solo resistor \"virtual\", ¿cómo queda el circuito completo?","opciones":["Como una serie simple, sumando ese valor con los demás resistores en serie","Como un nuevo bloque en paralelo","Ya no se puede resolver más","Igual que antes, sin cambios"],"respuesta":"Como una serie simple, sumando ese valor con los demás resistores en serie","explicacion":"Es el segundo paso de la técnica: con el bloque ya reducido a un número, el resto del circuito se trata con las reglas simples de serie."},{"pregunta":"Para hallar el voltaje de un resistor específico DENTRO del bloque en paralelo, ¿qué necesitás calcular primero?","opciones":["El voltaje que le llega a todo el bloque en paralelo","La corriente de la fuente completa","La resistencia de un resistor cualquiera fuera del bloque","No hace falta ningún cálculo previo"],"respuesta":"El voltaje que le llega a todo el bloque en paralelo","explicacion":"Recién con el voltaje del bloque completo (que se reparte igual a todas sus ramas, por ser paralelo) se puede calcular la corriente de un resistor específico adentro."}]}'::jsonb
where slug = 'circuitia-leer-mixto-por-el-bloque-paralelo';

update public.techniques
set contenido = '{"pasos":["Si aumenta la resistencia de un tramo, la resistencia TOTAL del circuito aumenta (o se queda igual, nunca baja) — así que la corriente que entrega la fuente nunca sube.","En una rama en PARALELO, cambiar la resistencia de UNA rama no afecta a las demás ramas hermanas — cada una sigue viendo el mismo voltaje de siempre, así que su propia corriente no cambia.","En SERIE, cualquier cambio en un resistor SÍ afecta a todos los demás — la misma corriente (ahora distinta) atraviesa a todos por igual.","Cuando la pregunta es sobre un resistor hermano en un bloque en paralelo conectado directo a la fuente, la respuesta más común y correcta es \"no cambia\" — no asumas que todo cambio en algún lado afecta a todo el circuito."],"quiz":[{"pregunta":"Si aumenta la resistencia de un tramo del circuito, ¿qué le pasa a la corriente TOTAL que entrega la fuente?","opciones":["Nunca sube (baja o queda igual)","Siempre sube","Se duplica siempre","No depende de la resistencia total"],"respuesta":"Nunca sube (baja o queda igual)","explicacion":"Más resistencia total en el camino siempre frena más (o igual) la corriente que la fuente puede entregar — nunca la aumenta."},{"pregunta":"En un bloque en PARALELO conectado directo a la fuente, si cambia la resistencia de UNA rama, ¿qué le pasa a la corriente de una rama HERMANA?","opciones":["No cambia","Siempre aumenta","Siempre disminuye","Se vuelve cero"],"respuesta":"No cambia","explicacion":"Cada rama en paralelo sigue viendo el mismo voltaje de siempre (compartido), así que su propia corriente ($I=\\frac{V}{R}$ con su propia R, sin cambios) no se ve afectada por lo que pase en una rama hermana."},{"pregunta":"En SERIE, si cambia la resistencia de un resistor, ¿qué le pasa a los demás resistores de esa misma rama?","opciones":["A todos los afecta — la misma corriente (ahora distinta) atraviesa a todos por igual","No les pasa nada, cada uno es independiente","Solo afecta al resistor inmediatamente siguiente","Solo afecta a la fuente, nunca a otros resistores"],"respuesta":"A todos los afecta — la misma corriente (ahora distinta) atraviesa a todos por igual","explicacion":"En serie todos comparten la misma corriente — si esa corriente cambia (porque cambió la resistencia total), afecta a todos los resistores de la rama por igual, a diferencia de una rama en paralelo."}]}'::jsonb
where slug = 'circuitia-estimar-sube-o-baja-sin-calcular';

update public.techniques
set contenido = jsonb_set(contenido, '{quiz}', '[{"pregunta":"¿Qué regla de derivación corresponde a $f(x) = (2x)(3x^{2})$?","opciones":["Regla del producto","Regla de la potencia","Regla del cociente","Regla de la cadena"],"respuesta":"Regla del producto","explicacion":"Son dos expresiones MULTIPLICADAS entre sí — eso siempre pide la regla del producto, nunca multiplicar las derivadas por separado."},{"pregunta":"¿Qué regla corresponde a $f(x) = (3x+2)^{4}$?","opciones":["Regla de la cadena","Regla de la potencia sola","Regla del producto","Regla del cociente"],"respuesta":"Regla de la cadena","explicacion":"Hay algo elevado a una potencia y adentro del paréntesis no es solo x — es una función dentro de otra, la señal clásica de la regla de la cadena."},{"pregunta":"¿Qué regla corresponde a $f(x) = 5x^{4}$?","opciones":["Regla de la potencia","Regla del producto","Regla del cociente","Regla de la cadena"],"respuesta":"Regla de la potencia","explicacion":"Es una sola potencia de x, sin nada multiplicado, dividido, ni un paréntesis con algo distinto de x adentro."}]'::jsonb)
where slug = 'calculia-reconocer-regla-derivacion';

update public.techniques
set contenido = jsonb_set(contenido, '{quiz}', '[{"pregunta":"¿Cuál es la fórmula de $\\int x^{n}\\,dx$ (con $n \\neq -1$)?","opciones":["$\\frac{x^{n+1}}{n+1} + C$","$\\frac{x^{n-1}}{n-1} + C$","$n\\cdot x^{n-1} + C$","$x^{n} + C$"],"respuesta":"$\\frac{x^{n+1}}{n+1} + C$","explicacion":"Subís el exponente uno $(n+1)$ y dividís por ese exponente NUEVO, nunca por el viejo."},{"pregunta":"¿Por qué $\\int (\\frac{1}{x})\\,dx$ no se resuelve con la regla de la potencia?","opciones":["Porque sería $n=-1$, y dividir por $(n+1)=0$ no tiene sentido","Porque $\\frac{1}{x}$ no es una potencia de x","Porque siempre da 0","Porque hace falta una calculadora"],"respuesta":"Porque sería $n=-1$, y dividir por $(n+1)=0$ no tiene sentido","explicacion":"Es el único caso especial de la tabla: $\\int (\\frac{1}{x})\\,dx = \\ln|x| + C$, distinto de la fórmula general de potencias."},{"pregunta":"¿En cuál de las dos integrales trigonométricas va el signo negativo?","opciones":["$\\int \\operatorname{sen}(x)\\,dx = -\\cos(x) + C$","$\\int \\cos(x)\\,dx = -\\operatorname{sen}(x) + C$","En ninguna de las dos","En las dos"],"respuesta":"$\\int \\operatorname{sen}(x)\\,dx = -\\cos(x) + C$","explicacion":"El signo negativo va SOLO en la integral del seno — $\\int \\cos(x)\\,dx = \\operatorname{sen}(x) + C$ nunca lleva signo negativo."}]'::jsonb)
where slug = 'calculia-tabla-integrales-comunes';

update public.techniques
set contenido = jsonb_set(contenido, '{quiz}', '[{"pregunta":"Una serie donde cada término se multiplica por la misma razón r para llegar al siguiente (como 3, 6, 12, 24...) es de tipo...","opciones":["Geométrica","Serie p","Ninguna de las dos, hace falta el criterio de la razón siempre","Aritmética"],"respuesta":"Geométrica","explicacion":"Es la \"pinta\" característica de una serie geométrica: razón constante entre términos consecutivos."},{"pregunta":"¿Cuándo converge una serie geométrica de razón r?","opciones":["Cuando $|r| < 1$","Cuando $r > 1$","Siempre converge","Cuando $r = 1$"],"respuesta":"Cuando $|r| < 1$","explicacion":"Es el criterio de convergencia de una serie geométrica — si $|r| \\geq 1$, diverge."},{"pregunta":"¿Cuándo converge una serie p, $\\sum \\frac{1}{n^{p}}$?","opciones":["Cuando $p > 1$","Cuando $p < 1$","Cuando $p = 0$","Siempre converge"],"respuesta":"Cuando $p > 1$","explicacion":"Es un criterio totalmente distinto al de las series geométricas $(|r|<1)$ — para series p el criterio es $p>1$, no hay que mezclarlos."}]'::jsonb)
where slug = 'calculia-identificar-tipo-serie';

update public.techniques
set contenido = jsonb_set(contenido, '{quiz}', '[{"pregunta":"¿Cuándo una EDO $\\frac{dy}{dx}$ es separable?","opciones":["Cuando se puede reescribir como $\\frac{dy}{dx} = f(x)\\cdot g(y)$","Solo cuando ya tiene y despejada","Nunca, siempre hace falta un método numérico","Solo si no tiene ninguna constante"],"respuesta":"Cuando se puede reescribir como $\\frac{dy}{dx} = f(x)\\cdot g(y)$","explicacion":"Si $\\frac{dy}{dx}$ es un producto de \"algo con x\" por \"algo con y\", la ecuación siempre se puede resolver por separación de variables, sin excepción."},{"pregunta":"Al separar variables, ¿qué se hace primero?","opciones":["Pasar todo lo de y (con $dy$) a un lado y todo lo de x (con $dx$) al otro","Integrar directamente sin reordenar nada","Derivar ambos lados","Reemplazar y por una constante"],"respuesta":"Pasar todo lo de y (con $dy$) a un lado y todo lo de x (con $dx$) al otro","explicacion":"Es el paso 1 de la técnica: $\\frac{dy}{g(y)} = f(x)\\,dx$, antes de poder integrar cada lado por separado."},{"pregunta":"Si al integrar te queda $\\ln|y| = x^{2} + C_{1}$, ¿qué operación despeja y?","opciones":["Aplicar exponencial en ambos lados","Aplicar logaritmo otra vez","Dividir ambos lados por $x^{2}$","Restar $C_{1}$ de ambos lados y listo"],"respuesta":"Aplicar exponencial en ambos lados","explicacion":"$e^{\\ln|y|} = e^{x^{2}+C_{1}}$ da $|y| = e^{C_{1}}\\cdot e^{x^{2}}$ — como $e^{C_{1}}$ es solo otra constante, se renombra como $A$: $y = A\\cdot e^{x^{2}}$."}]'::jsonb)
where slug = 'calculia-separar-variables-edo';

update public.techniques
set contenido = jsonb_set(contenido, '{quiz}', '[{"pregunta":"Al calcular $\\frac{\\partial f}{\\partial x}$ de $f(x,y) = 3x^{2}y$, ¿cómo se trata la y?","opciones":["Como si fuera una constante (un coeficiente fijo)","Se deriva igual que x","Desaparece del resultado","Se reemplaza por 0"],"respuesta":"Como si fuera una constante (un coeficiente fijo)","explicacion":"El único cambio de hábito respecto de derivar de siempre es tratar la otra letra como un número fijo — nunca se deriva ni desaparece."},{"pregunta":"¿Cuál es el error más común al calcular una derivada parcial?","opciones":["Derivar las dos variables a la vez, en vez de dejar fija la que no se pidió","Olvidarse del signo","Usar la regla del producto","Multiplicar por 2 de más"],"respuesta":"Derivar las dos variables a la vez, en vez de dejar fija la que no se pidió","explicacion":"Si te piden $\\frac{\\partial}{\\partial x}$, la potencia de y del resultado tiene que quedar EXACTAMENTE igual que en el original — derivarla también es el error típico."},{"pregunta":"Según el truco de \"tapar con un dedo\", ¿qué significa tapar la letra que no te pidieron?","opciones":["Derivar lo que queda visible como si fuera una función de una sola variable","Borrarla del resultado final","Reemplazarla por 1","Sumarle 1 al exponente de esa letra"],"respuesta":"Derivar lo que queda visible como si fuera una función de una sola variable","explicacion":"Es el atajo mental de la técnica: tapás la letra que no te pidieron, derivás lo visible con la regla de siempre, y después destapás sin haber tocado esa letra."}]'::jsonb)
where slug = 'calculia-derivar-parciales';

